  async function chooseFromLibrary(){if(profileUploading)return;try{const permission=await ImagePicker.requestMediaLibraryPermissionsAsync();if(!permission.granted)return Alert.alert('Accès aux photos','Autorise Onlive à accéder à tes photos pour choisir ta photo de profil.');const result=await ImagePicker.launchImageLibraryAsync({mediaTypes:ImagePicker.MediaTypeOptions.Images,allowsEditing:true,aspect:[1,1],quality:.75,exif:false});if(!result.canceled&&result.assets?.[0])await saveProfileAsset(result.assets[0])}catch(e:any){Alert.alert('Photo impossible',e?.message||'Impossible d’ouvrir la photothèque.')}}
