  function pickProfilePhoto(){if(profileUploading)return;Alert.alert('Photo de profil','Que veux-tu faire ?',[{text:'Prendre une photo',onPress:takeProfilePhoto},{text:'Choisir dans la photothèque',onPress:chooseFromLibrary},{text:'Annuler',style:'cancel'}])}

  async function autoLoadContacts(){if(reviewMode){const demo:Match[]=[{userId:'review-demo-alexandre',name:'Alexandre R.',phone:'+33900000001'},{userId:'review-demo-thomas',name:'Thomas Dupont',phone:'+33900000002'},{userId:'review-demo-papa',name:'Papa',phone:'+33900000003'}];setMatches(demo);await refreshLiveFriends(demo);return}const perm=await Contacts.getPermissionsAsync();if(perm.status==='granted')await loadContacts(true)}
  async function loadContacts(silent=false){const perm=silent?await Contacts.getPermissionsAsync():await Contacts.requestPermissionsAsync();if(perm.status!=='granted'){setContactsPermission('denied');if(!silent)Alert.alert('Accès refusé','Autorise les contacts dans les réglages.');return}setContactsPermission('granted');const{data}=await Contacts.getContactsAsync({fields:[Contacts.Fields.PhoneNumbers],pageSize:0});setDeviceContacts(data);const local=new Map<string,Contacts.Contact>();data.forEach(c=>contactPhones(c).forEach(p=>local.set(p,c)));const allPhones=[...local.keys()],rows:any[]=[];for(let i=0;i<allPhones.length;i+=300){const{data:found,error}=await supabase.rpc('match_contact_phones',{phone_list:allPhones.slice(i,i+300)});if(error){if(!silent)Alert.alert('Erreur contacts',error.message);return}rows.push(...(found||[]))}const ids=[...new Set(rows.map((r:any)=>r.user_id).filter(Boolean))];const avatarMap=new Map<string,string>();if(ids.length){const{data:profiles}=await supabase.from('profiles').select('id,avatar_url').in('id',ids);(profiles||[]).forEach((p:any)=>{if(p.avatar_url)avatarMap.set(p.id,p.avatar_url)})}const found:Match[]=rows.flatMap((p:any)=>{const normalized=normalizePhone(p.phone_e164||''),c=local.get(normalized);if(!c)return[];return[{userId:p.user_id,name:c.name||'Contact',phone:normalized,image:avatarMap.get(p.user_id)}]});if(userId&&found.length){const aliasRows=[...new Map(found.map(m=>[m.userId,m])).values()].map(m=>({owner_user_id:userId,contact_user_id:m.userId,local_name:m.name,updated_at:new Date().toISOString()}));const{error:aliasError}=await supabase.from('contact_aliases').upsert(aliasRows,{onConflict:'owner_user_id,contact_user_id'});if(aliasError)console.warn('Contact alias sync failed',aliasError)}setMatches(found);await refreshLiveFriends(found)}
  async function refreshLiveFriends(list=matches){if(reviewMode){if(!selectedProgram&&!tvBrowsing){setLiveFriends([]);setFriendsLoading(false);return}setLiveFriends([{...list[0],programId:selectedProgram?.id||null,program:selectedProgram?.title||'',channel:selectedProgram?.channel||'',since:'depuis 12 min'},{...list[1],programId:selectedProgram?.id||null,program:selectedProgram?.title||'',channel:selectedProgram?.channel||'',since:'depuis 8 min'},{...list[2],programId:selectedProgram?.id||null,program:selectedProgram?.title||'',channel:selectedProgram?.channel||'',since:'depuis 4 min'}]);setFriendsLoading(false);return}if(!list.length){setLiveFriends([]);setFriendsLoading(false);return}const{data,error}=await supabase.from('live_status').select('user_id,program_id,is_live,started_at,presence_mode,last_seen_at,updated_at,tv_programs(title,channel,start_time,program_date)').in('user_id',list.map(x=>x.userId)).eq('is_live',true);if(error){setFriendsLoading(false);return}const nowMs=Date.now();setLiveFriends((data||[]).flatMap((r:any)=>{const m=list.find(x=>x.userId===r.user_id);if(!m)return[];const mode=r.presence_mode||(r.program_id?'watching':'browsing');const seen=r.last_seen_at||r.updated_at;if(mode==='browsing'){if(!seen||nowMs-new Date(seen).getTime()>=2*60*60*1000)return[];const mins=Math.max(0,Math.floor((nowMs-new Date(seen).getTime())/60000));return[{...m,programId:null,program:'',channel:'',since:`depuis ${mins} min`}]};if(mode!=='watching'||!r.program_id)return[];const mins=r.started_at?Math.max(0,Math.floor((nowMs-new Date(r.started_at).getTime())/60000)):0;const pd=r.tv_programs?.program_date,pt=r.tv_programs?.start_time;if(pd&&pt){const start=new Date(`${pd}T${String(pt).slice(0,8)}`).getTime();if(Number.isFinite(start)&&nowMs>start+4*60*60*1000)return[]}return[{...m,programId:r.program_id,program:r.tv_programs?.title||'Programme',channel:r.tv_programs?.channel||'',since:`depuis ${mins} min`,startTime:pt?String(pt).slice(0,5):undefined}]}));setFriendsLoading(false)}

  async function setBrowsingPresence(active:boolean){if(!userId)return;if(active){const t=new Date().toISOString();const{error}=await supabase.from('live_status').upsert({user_id:userId,program_id:null,is_live:true,presence_mode:'browsing',started_at:t,last_seen_at:t,updated_at:t},{onConflict:'user_id'});if(error)return Alert.alert('Statut impossible',error.message);setSelectedProgram(null);setTvBrowsing(true)}else{const{error}=await supabase.from('live_status').upsert({user_id:userId,program_id:null,is_live:false,presence_mode:'off',started_at:null,last_seen_at:new Date().toISOString(),updated_at:new Date().toISOString()},{onConflict:'user_id'});if(error)return Alert.alert('Statut impossible',error.message);setTvBrowsing(false);setSelectedProgram(null)}}
  async function chooseProgram(program:Program){if(!userId)return;setProgramGuideOpen(false);if(selectedProgram?.id===program.id)return goOfflive();if(!programSelectable(program,now))return Alert.alert('Programme à venir',`Tu pourras te positionner Onlive 15 minutes avant ${program.time}.`);if(reviewMode){setTvBrowsing(false);setSelectedProgram(program);onReviewProgramChange?.({id:program.id,title:program.title,channel:program.channel});const demo:Match[]=[{userId:'review-demo-alexandre',name:'Alexandre R.',phone:'+33900000001'},{userId:'review-demo-thomas',name:'Thomas Dupont',phone:'+33900000002'},{userId:'review-demo-papa',name:'Papa',phone:'+33900000003'}];setLiveFriends(demo.map((m,i)=>({...m,programId:program.id,program:program.title,channel:program.channel,since:`depuis ${12-i*4} min`})));return}if(programSource!=='supabase')return Alert.alert('Programme de démonstration','Reconnecte-toi avec internet pour publier un vrai statut.');const{error}=await supabase.from('live_status').upsert({user_id:userId,program_id:program.id,is_live:true,presence_mode:'watching',started_at:new Date().toISOString(),last_seen_at:new Date().toISOString(),updated_at:new Date().toISOString()},{onConflict:'user_id'});if(error)return Alert.alert('Impossible de passer Onlive',error.message);setTvBrowsing(false);setSelectedProgram(program)}
  async function goOfflive(){if(reviewMode){setSelectedProgram(null);setLiveFriends([]);onReviewProgramChange?.(null);return}if(userId){const{error}=await supabase.from('live_status').upsert({user_id:userId,program_id:null,is_live:false,presence_mode:'off',started_at:null,last_seen_at:new Date().toISOString(),updated_at:new Date().toISOString()},{onConflict:'user_id'});if(error)return Alert.alert('Impossible de passer Offlive',error.message)}setSelectedProgram(null);setTvBrowsing(false)}
  async function bumpScore(phoneValue:string){const next={...contactScores,[phoneValue]:(contactScores[phoneValue]||0)+1};setContactScores(next);await AsyncStorage.setItem(SCORE_KEY,JSON.stringify(next))}
  async function inviteContact(c:Contacts.Contact){const p=contactPhones(c)[0]||'';if(p)await bumpScore(p);await Share.share({message:`Salut ${c.name||''} ! Rejoins-moi sur Onlive 📺✨ ${INVITE_URL}`,url:INVITE_URL})}
