  <Modal visible={profileOpen} transparent animationType="fade" onRequestClose={()=>setProfileOpen(false)}><View style={s.modalBackdropCenter}><View style={s.profileModal}><View style={s.profileModalHead}><Text style={s.profileModalTitle}>Mon profil</Text><TouchableOpacity onPress={()=>setProfileOpen(false)}><Ionicons name="close" size={25}/></TouchableOpacity></View><View style={s.profileBigWrap}>{profileAvatar?<Image source={{uri:profileAvatar}} style={s.profileBigImage}/>:<LinearGradient colors={['#4932ff','#ed00b3']} style={s.profileBigFallback}><Text style={s.profileBigInitial}>{initials(profileName).slice(0,1)}</Text></LinearGradient>}<View style={s.cameraBadge}><Ionicons name="camera" size={17} color="#fff"/></View></View><Text style={s.profileName}>{profileName}</Text><Text style={s.profileHint}>Cette photo sera visible par tes proches sur Onlive.</Text><TouchableOpacity disabled={profileUploading} onPress={pickProfilePhoto}><LinearGradient colors={['#4932ff','#ed00b3']} style={s.profilePhotoButton}><Ionicons name="camera-outline" size={19} color="#fff"/><Text style={s.profilePhotoButtonText}>{profileUploading?'Enregistrement…':profileAvatar?'Changer ma photo':'Ajouter une photo'}</Text></LinearGradient></TouchableOpacity><TouchableOpacity onPress={()=>{setProfileOpen(false);onOpenAccount?.()}} style={s.profileAccountButton}><Ionicons name="settings-outline" size={19} color="#5d19cf"/><View style={{flex:1}}><Text style={s.profileAccountTitle}>Compte</Text><Text style={s.profileAccountText}>Confidentialité et suppression du compte</Text></View><Ionicons name="chevron-forward" size={19} color="#999"/></TouchableOpacity></View></View></Modal>

