function FavoriteRow({item,active,onPress}:{item:any;active:boolean;onPress:()=>void}){return<TouchableOpacity onPress={onPress} style={s.favoriteRow}><View style={[s.favoriteIcon,{backgroundColor:active?'#17171c':'#ececf2'}]}><Ionicons name={item.icon as any} size={23} color={active?'#fff':'#666'}/></View><View style={{flex:1}}><Text style={s.favoriteLabel}>{item.label}</Text><Text style={s.favoriteMeta}>{item.group}</Text></View><Ionicons name={active?'star':'star-outline'} size={25} color={active?'#FFD43B':'#aaa'}/></TouchableOpacity>}
