function SuggestionBox({value,onChange,placeholder,onSubmit,disabled}:{value:string;onChange:(v:string)=>void;placeholder:string;onSubmit:()=>void;disabled:boolean}){return<View style={s.suggestionBox}><Text style={s.suggestionTitle}>Tu ne trouves pas ce que tu veux ?</Text><View style={s.suggestionRow}><TextInput value={value} onChangeText={onChange} placeholder={placeholder} placeholderTextColor="#999" style={s.suggestionInput}/><TouchableOpacity disabled={disabled||!value.trim()} onPress={onSubmit} style={[s.suggestionButton,(disabled||!value.trim())&&s.suggestionButtonDisabled]}><Ionicons name="add" size={20} color="#fff"/></TouchableOpacity></View></View>}

function BottomNav({active,unreadCount,onHome,onDiscussions,onContacts}:{active:'home'|'contacts';unreadCount:number;onHome:()=>void;onDiscussions?:()=>void;onContacts:()=>void}){return<View style={s.bottomNav}><TouchableOpacity onPress={onHome} style={s.navItem}>{active==='home'?<LinearGradient colors={['#4932ff','#ed00b3']} style={s.navActive}><Ionicons name="home" size={25} color="#fff"/><Text style={s.navActiveText}>Accueil</Text></LinearGradient>:<View style={s.navInactive}><Ionicons name="home-outline" size={25} color="#6b2cff"/><Text style={s.navInactiveText}>Accueil</Text></View>}</TouchableOpacity><TouchableOpacity onPress={onDiscussions} style={s.navItem}><View style={s.navInactive}><View><Ionicons name="chatbubbles-outline" size={25} color="#9a25df"/>{unreadCount>0&&<View style={s.navBadge}><Text style={s.navBadgeText}>{unreadCount>99?'99+':unreadCount}</Text></View>}</View><Text style={[s.navInactiveText,{color:'#9a25df'}]}>Discussions</Text></View></TouchableOpacity><TouchableOpacity onPress={onContacts} style={s.navItem}>{active==='contacts'?<LinearGradient colors={['#4932ff','#ed00b3']} style={s.navActive}><Ionicons name="people" size={27} color="#fff"/><Text style={s.navActiveText}>Contacts</Text></LinearGradient>:<View style={s.navInactive}><Ionicons name="people-outline" size={27} color="#d700b0"/><Text style={[s.navInactiveText,{color:'#d700b0'}]}>Contacts</Text></View>}</TouchableOpacity></View>}

